/**
 * Email Value Object
 * 
 * Immutable, validated value object representing an email address.
 * Ensures only valid emails can be created - invalid emails throw at construction.
 */

export class Email {
  readonly value: string;

  constructor(email: string) {
    this.validate(email);
    this.value = email.toLowerCase().trim();
  }

  private validate(email: string): void {
    if (!email || email.trim().length === 0) {
      throw new Error("Email cannot be empty");
    }

/**
 * Password Value Object
 * 
 * Immutable, validated value object representing a hashed password.
 * Never stores plain text, only accepts pre-hashed passwords.
 */

export class Password {
  readonly hash: string;

  constructor(hash: string) {
    this.validate(hash);
    this.hash = hash;
  }

  private validate(hash: string): void {
    if (!hash || hash.trim().length === 0) {
      throw new Error("Password hash cannot be empty");
    }

